[TFMPageType('OrderList', "Order List")]
class TFMPageOrderListConfiguration extends TFMListPageConfiguration
{
    boolean			automaticOrderSelectionAfterFilter;
    boolean			automaticAcceptAfterLastScan;
    boolean			automaticAcceptOnOpen;
    boolean			filterEnabled;
    TFMListId		listId;
    TFMPageID		navigateTo;
    TFMServiceID	serviceId;
    TFMPageID		searchNavigateTo;

    TFMOfflineModeTypes              operationMode;
    TFMLineCompletedDefinitionTypes  lineCompletionDefinition;
    TFMDocumentTypeId                lineSelectionDocument;

    boolean				cancelOrderEnabled;
    boolean				clearCompletedOrdersEnabled;
    boolean				postAllOrdersEnabled;
    boolean				registerOrderEnabled;
    boolean				viewErrorMessageEnabled;
    boolean				toggleShowPostedOrdersEnabled;
    boolean				unlockOrderEnabled;

    TFMWorkflowName		workflowName;
    TFMPageTitleString	unlockOrderTitle;


}

